export const unitoolsRecipes: readonly LibraryRecipeData[] = [
  {"id":"unitools-apfelstrudel","name":"Яблочный штрудель","description":"Яблоки с корицей и изюмом в тесте, растянутом до прозрачности. Тесто тянут руками, а не раскатывают.","category":"Десерты","tags":["австрийская кухня"],"ingredients":[["fdc-168896",250,"Мука высокобелковая"],["builtin-110",125,"Тёплая вода"],["fdc-172336",42.0,"Растительное масло"],["fdc-168203",1000,"Кислые яблоки"],["fdc-169655",100,"Сахар"],["fdc-171320",5.2,"Корица"],["fdc-168165",80,"Изюм"],["fdc-174928",80,"Панировочные сухари"],["fdc-173430",120,"Сливочное масло"],["fdc-167746",58.0,"Лимон"]],"servings":8,"prep":60,"cook":45,"difficulty":"Сложный","steps":["Замесите тесто из муки, тёплой воды, масла и щепотки соли и вымешивайте десять минут — оно должно стать гладким и очень эластичным. Смажьте маслом, накройте и оставьте на час.","Обжарьте сухари в половине масла до золотистого цвета. Яблоки смешайте с сахаром, корицей, изюмом, соком и цедрой лимона.","Расстелите на столе полотенце, присыпьте мукой и растяните тесто тыльной стороной ладоней от центра к краям, пока оно не станет прозрачным. Толстые края обрежьте.","Смажьте тесто растопленным маслом, посыпьте сухарями треть поверхности и выложите на них яблоки, отступив от краёв.","Заверните рулетом, поднимая полотенце, — руками тесто порвётся. Подверните края, переложите швом вниз и смажьте маслом.","Выпекайте при 190 °C сорок минут, смазывая маслом дважды за это время. Подавайте тёплым с сахарной пудрой."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker"},
  {"id":"unitools-trdelnik","name":"Трдельник","description":"Дрожжевая полоска теста, намотанная на валик, запечённая и обвалянная в сахаре с орехами.","category":"Десерты","tags":["чешская кухня"],"ingredients":[["fdc-168936",500,"Мука"],["fdc-172217",226.8921,"Тёплое молоко"],["fdc-175043",7,"Сухие дрожжи"],["fdc-169655",60,"Сахар в тесто"],["fdc-173430",80,"Сливочное масло"],["fdc-171287",100.0,"Яйца"],["fdc-169655",150,"Сахар для обваливания"],["fdc-170187",100,"Грецкие орехи"],["fdc-171320",5.2,"Корица"],["fdc-173468",6.0,"Соль"]],"servings":6,"prep":90,"cook":20,"difficulty":"Средний","steps":["Распустите дрожжи с ложкой сахара в тёплом молоке, дайте вспениться десять минут.","Замесите тесто из муки, опары, яиц, сахара и соли, вымешивайте десять минут, затем вмешивайте мягкое масло по кусочку. Дайте подойти час.","Раскатайте тесто и нарежьте полосками шириной два сантиметра. Смажьте валики маслом и обваляйте в сахаре.","Намотайте полоску на валик внахлёст на треть ширины, слегка натягивая. Прокатайте по столу, чтобы слои сцепились.","Смажьте маслом, обваляйте в смеси сахара с орехами и корицей и запекайте при 190 °C восемнадцать минут, поворачивая каждые пять.","Дайте остыть три минуты и снимите с валика, провернув. Горячий трдельник рвётся, полностью остывший прилипает."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker"},
  {"id":"unitools-tabbouleh","name":"Табуле","description":"Салат из петрушки с небольшим количеством булгура, а не наоборот. Зелени здесь в десять раз больше крупы.","category":"Салаты","tags":["ливанская кухня"],"ingredients":[["fdc-170416",200,"Петрушка"],["fdc-173475",30,"Мята"],["fdc-170688",40,"Мелкий булгур"],["fdc-170457",492.0,"Помидоры"],["fdc-170005",60.0,"Зелёный лук"],["fdc-167747",96.0,"Сок лимона"],["fdc-171413",54.7787,"Оливковое масло"],["fdc-171315",0.95,"Душистый перец молотый"]],"servings":4,"prep":25,"cook":0,"difficulty":"Простой","steps":["Промойте булгур и залейте соком одного лимона. Оставьте набухать пятнадцать минут.","Вымойте петрушку заранее и обсушите досуха — лучше час на полотенце. Оборвите толстые стебли и рубите ножом мелко, но без фанатизма.","Нарежьте помидоры мелким кубиком и посолите отдельно — они пустят сок, который пойдёт в булгур.","Смешайте всё вместе с соком второго лимона, маслом и душистым перцем. Дайте постоять десять минут перед подачей."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль."},
  {"id":"unitools-croissant","name":"Круассан","description":"Слоёное дрожжевое тесто с двадцатью семью слоями масла. Всё решает температура: тесто и масло должны быть одинаково холодными.","category":"Выпечка","tags":["французская кухня"],"ingredients":[["fdc-168896",500,"Мука высокобелковая"],["fdc-172217",288.7718,"Холодное молоко"],["fdc-175042",15,"Свежие дрожжи"],["fdc-169655",55,"Сахар"],["fdc-173468",11,"Соль"],["fdc-173430",40,"Масло в тесто"],["fdc-173430",280,"Масло для слоения"],["fdc-171287",50.0,"Яйцо для смазки"]],"servings":8,"prep":180,"cook":20,"difficulty":"Сложный","steps":["Замесите тесто из муки, холодного молока, дрожжей, сахара, соли и мягкого масла пять минут. Не перемешивайте дольше: сильная клейковина помешает раскатке.","Расплющите тесто в прямоугольник, заверните и уберите в холодильник минимум на четыре часа, лучше на ночь.","Отбейте холодное масло скалкой в квадрат толщиной в сантиметр и держите в холоде. Оно должно гнуться, но не ломаться и не таять.","Раскатайте тесто вдвое больше масляного квадрата, положите масло по центру и заверните края конвертом, защипнув швы.","Раскатайте в длинный прямоугольник и сложите втрое. Уберите в холод на сорок минут. Повторите ещё два раза — всего три сложения.","Раскатайте пласт толщиной четыре миллиметра, нарежьте треугольниками с основанием десять сантиметров и сверните от основания к вершине, слегка натягивая.","Расстаивайте два часа при 25 °C — не теплее, иначе масло вытечет. Смажьте яйцом и выпекайте при 200 °C восемнадцать минут."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker"},
  {"id":"unitools-baklava","name":"Пахлава","description":"Сорок слоёв юфки с фисташками, залитые сиропом. Горячая пахлава заливается холодным сиропом, и только так.","category":"Десерты","tags":["турецкая кухня"],"ingredients":[["fdc-172791",500,"Тесто юфка или фило"],["fdc-170184",400,"Фисташки"],["fdc-171314",300,"Топлёное масло"],["fdc-169655",500,"Сахар"],["builtin-110",400,"Вода"],["fdc-167747",15.25,"Лимонный сок"]],"servings":12,"prep":60,"cook":60,"difficulty":"Сложный","steps":["Сварите сироп: сахар с водой довести до кипения, варить пятнадцать минут, добавить лимонный сок и полностью остудить.","Растопите масло и дайте отстояться — используйте только прозрачный верхний слой, осадок вылейте.","Уложите в смазанную форму двадцать листов, смазывая каждый маслом. Посыпьте фисташками ровным слоем.","Накройте ещё двадцатью листами, так же смазывая каждый. Верхний слой смажьте особенно щедро.","Разрежьте острым ножом на ромбы до самого дна формы.","Выпекайте при 170 °C час до глубокого золотого цвета. Достаньте и сразу залейте холодным сиропом по надрезам.","Оставьте на шесть часов, лучше на ночь. Резать и подавать раньше бессмысленно: сироп не дошёл до нижних слоёв."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker"},
  {"id":"unitools-karjalanpiirakka","name":"Карельские пирожки","description":"Ржаная корзиночка с рисовой кашей, смазанная маслом после выпечки и поданная с яичным маслом.","category":"Выпечка","tags":["финская кухня"],"ingredients":[["fdc-168886",250,"Ржаная мука"],["builtin-110",150,"Вода"],["fdc-168881",150,"Круглый рис"],["fdc-172217",721.9294,"Молоко"],["fdc-173430",100,"Сливочное масло"],["fdc-171287",150.0,"Яйца"]],"servings":8,"prep":60,"cook":25,"difficulty":"Сложный","steps":["Сварите рис в молоке на слабом огне сорок минут до состояния жидковатой каши. Посолите и остудите.","Замесите тесто из ржаной муки, воды и соли, вымешивайте пять минут. Оно будет плотным и не липким.","Разделите на шестнадцать шариков и раскатайте каждый в овал толщиной в полмиллиметра. Подпыляйте ржаной мукой, а не пшеничной.","Выложите ложку каши по центру, оставив свободными края, и защипните края гофрировкой, оставив начинку открытой.","Выпекайте при 250 °C пятнадцать минут — коротко и очень горячо, иначе тонкое тесто высохнет.","Растопите половину масла с равным количеством горячей воды и окуните горячие пирожки. Накройте полотенцем на десять минут.","Разомните варёные яйца с оставшимся мягким маслом и солью — это мунавой, яичное масло. Подавайте им пирожки."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль."},
  {"id":"unitools-soda-bread","name":"Содовый хлеб","description":"Хлеб на соде и пахте без дрожжей и без расстойки. От замеса до духовки — три минуты.","category":"Выпечка","tags":["ирландская кухня"],"ingredients":[["fdc-168936",350,"Мука"],["fdc-168893",150,"Цельнозерновая мука"],["fdc-172225",414.2218,"Пахта"],["fdc-175040",4.6,"Сода"],["fdc-173468",6.0,"Соль"],["fdc-173904",10.2273,"Овсяные хлопья"]],"servings":8,"prep":10,"cook":45,"difficulty":"Простой","steps":["Разогрейте духовку до 220 °C заранее. Хлеб должен отправиться в неё сразу после замеса, ждать он не может.","Смешайте обе муки, соду и соль в миске и хорошо перемешайте, чтобы сода разошлась равномерно.","Влейте пахту и перемешайте ножом или рукой ровно до соединения. Тесто будет липким и неровным — так и надо.","Выложите на присыпанный мукой противень, придайте форму круглой буханки и прорежьте глубокий крест почти до дна.","Посыпьте овсяными хлопьями и выпекайте пятнадцать минут при 220 °C, затем тридцать при 190 °C.","Готовый хлеб звучит глухо, если постучать по дну. Остудите на решётке минимум час: горячий содовый хлеб не режется."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker"},
  {"id":"unitools-zagorski-strukli","name":"Загорски штрукли","description":"Тонкое тесто с творожной начинкой, отваренное и запечённое под сливками.","category":"Основные блюда","tags":["хорватская кухня"],"ingredients":[["fdc-168936",300,"Мука"],["builtin-110",150,"Тёплая вода"],["fdc-172336",28.0,"Растительное масло"],["fdc-171287",50.0,"Яйцо"],["fdc-172181",600,"Сухой творог"],["fdc-171287",100.0,"Яйца в начинку"],["fdc-171257",200,"Сметана"],["fdc-170859",251.9145,"Сливки"],["fdc-173430",60,"Сливочное масло"]],"servings":6,"prep":60,"cook":45,"difficulty":"Сложный","steps":["Замесите тесто из муки, тёплой воды, масла, яйца и соли и вымешивайте десять минут до эластичности. Смажьте маслом и оставьте на полчаса.","Разомните творог вилкой с яйцами, сметаной и солью. Начинка должна быть плотной, а не текучей.","Растяните тесто на полотенце руками до прозрачности, смажьте растопленным маслом и разложите начинку по трети поверхности.","Сверните рулетом, поднимая полотенце, и нарежьте на куски по восемь сантиметров, прижимая края ребром ладони, чтобы они запечатались.","Отварите в подсоленной воде пять минут после всплытия и выньте шумовкой.","Уложите в форму, залейте сливками, полейте растопленным маслом и запекайте при 200 °C двадцать пять минут до румяной корочки."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль."},
  {"id":"unitools-saltibarsciai","name":"Шалтибарщяй","description":"Холодный свекольный суп на кефире, ярко-розовый, с огурцом, укропом и варёной картошкой отдельно.","category":"Супы","tags":["литовская кухня"],"ingredients":[["fdc-169145",500,"Свёкла"],["fdc-170904",1027.1009,"Кефир"],["fdc-168409",602.0,"Огурцы"],["fdc-171287",200.0,"Яйца"],["fdc-172233",40,"Укроп"],["fdc-170005",40,"Зелёный лук"],["fdc-170026",800,"Картофель"],["fdc-171257",145.823,"Сметана"]],"servings":4,"prep":20,"cook":40,"difficulty":"Простой","steps":["Отварите свёклу до мягкости, остудите полностью и натрите на крупной тёрке.","Нарежьте огурцы соломкой, порубите укроп и зелёный лук.","Смешайте свёклу, огурцы и зелень со сметаной и посолите — до кефира, чтобы соль разошлась.","Влейте холодный кефир и размешайте. Суп станет ровного розового цвета.","Уберите в холодильник на час. Тёплый шалтибарщяй не имеет смысла.","Отварите картофель и подайте горячим на отдельной тарелке. В суп положите половинки яиц."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль."},
  {"id":"unitools-draniki","name":"Драники","description":"Картофельные оладьи из тёртого сырого картофеля, жаренные до хрустящей корки, со сметаной.","category":"Основные блюда","tags":["белорусская кухня"],"ingredients":[["fdc-170026",1000,"Картофель"],["fdc-170000",110.0,"Лук"],["fdc-172336",92.1432,"Растительное масло"],["fdc-171257",194.4306,"Сметана"],["fdc-172233",20,"Укроп"]],"servings":4,"prep":20,"cook":25,"difficulty":"Простой","steps":["Натрите картофель и лук на мелкой тёрке в одну миску.","Дайте массе постоять три минуты и слейте отстоявшуюся сверху воду, не трогая осадок.","Посолите и поперчите. Ничего больше не добавляйте.","Разогрейте масло на среднем огне и выкладывайте массу столовой ложкой, приплющивая до толщины в полсантиметра.","Жарьте по три-четыре минуты с каждой стороны до тёмно-золотой хрустящей корки.","Выложите на бумагу и подавайте немедленно со сметаной и укропом."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-chakalaka","name":"Чакалака","description":"Острая овощная закуска из моркови, перца и фасоли с карри. К брааю, к пап или сама по себе.","category":"Гарниры","tags":["южноафриканская кухня"],"ingredients":[["fdc-170393",244.0,"Морковь"],["fdc-170108",357.0,"Перец сладкий"],["fdc-170000",220.0,"Лук"],["fdc-175182",400,"Фасоль в томате"],["fdc-170457",400,"Помидоры"],["fdc-170924",6.3,"Карри молотое"],["fdc-171329",2.3,"Паприка"],["fdc-170106",90.0,"Перец чили"],["fdc-169230",12.0,"Чеснок"],["fdc-169231",20,"Имбирь"],["fdc-172336",46.0716,"Растительное масло"]],"servings":6,"prep":20,"cook":20,"difficulty":"Простой","steps":["Натрите морковь на крупной тёрке, перец и лук нарежьте тонкой соломкой.","Обжарьте лук с чесноком, имбирём и чили в масле до мягкости, пять минут.","Добавьте карри и паприку и прогрейте минуту — специи должны раскрыться в масле.","Всыпьте перец и морковь и жарьте пять минут на сильном огне, помешивая.","Влейте помидоры, посолите и тушите семь минут, пока соус не загустеет.","Вмешайте фасоль, прогрейте три минуты и снимите с огня. Овощи должны остаться упругими."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-burek-bosanski","name":"Боснийский бурек","description":"Спираль из тончайшего вытянутого теста с мясной начинкой. В Боснии буреком называют только мясной.","category":"Основные блюда","tags":["боснийская кухня"],"ingredients":[["fdc-168936",500,"Мука"],["builtin-110",280,"Вода тёплая"],["fdc-171796",600,"Говяжий фарш"],["fdc-170000",220.0,"Лук"],["fdc-172336",138.2148,"Растительное масло"],["fdc-172237",5.0,"Уксус"],["fdc-171284",414.2218,"Йогурт"]],"servings":6,"prep":75,"cook":45,"difficulty":"Сложный","steps":["Замесите тесто из муки, тёплой воды, ложки масла, уксуса и соли и вымешивайте пятнадцать минут до эластичности.","Разделите на четыре шара, смажьте маслом, накройте и оставьте на сорок минут.","Смешайте сырой фарш с луком, солью, перцем и двумя ложками воды — вода нужна, чтобы начинка не пересохла.","Растяните шар руками на застеленном скатертью столе до прозрачного листа, начиная от центра и двигаясь к краям.","Сбрызните лист маслом, выложите начинку полосой вдоль края и сверните в длинный тонкий рулет.","Уложите рулеты спиралью в круглую форму от центра, смажьте маслом и пеките при 200 °C сорок минут.","Сбрызните горячий бурек водой и накройте полотенцем на пять минут — корка станет мягче. Подавайте с йогуртом."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-byrek-me-spinaq","name":"Бюрек со шпинатом","description":"Пирог из тонкого теста со шпинатом и брынзой, слоями, залитыми маслом.","category":"Основные блюда","tags":["албанская кухня"],"ingredients":[["fdc-172791",500,"Тесто фило"],["fdc-168462",1000,"Шпинат"],["fdc-173420",400,"Брынза"],["fdc-170005",90.0,"Зелёный лук"],["fdc-171413",164.3362,"Оливковое масло"],["fdc-172233",30,"Укроп"]],"servings":8,"prep":35,"cook":45,"difficulty":"Простой","steps":["Ошпарьте шпинат кипятком, откиньте и отожмите руками досуха.","Нарежьте шпинат, смешайте с раскрошенной брынзой, зелёным луком, укропом и перцем. Соль добавляйте осторожно — брынза солёная.","Смажьте форму маслом и уложите три листа фило, промазывая каждый.","Распределите треть начинки, накройте двумя листами с маслом и повторите ещё дважды.","Закройте тремя листами сверху, подверните края внутрь и щедро смажьте маслом.","Нарежьте квадратами до низа острым ножом — резать после выпечки не получится.","Пеките при 190 °C сорок пять минут до тёмно-золотой хрустящей корки."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-flia","name":"Флия","description":"Слоёный пирог из жидкого теста, наливаемого по одному слою под раскалённой крышкой саче.","category":"Основные блюда","tags":["косовская кухня"],"ingredients":[["fdc-168936",600,"Мука"],["builtin-110",900,"Вода"],["fdc-171257",388.8613,"Сметана"],["fdc-173430",150,"Сливочное масло"],["fdc-171284",310.6663,"Йогурт"],["fdc-169640",100,"Мёд"],["fdc-173468",12.0,"Соль"]],"servings":8,"prep":30,"cook":90,"difficulty":"Сложный","steps":["Взбейте муку с водой и солью в жидкое тесто без комков — гуще блинного, но текучее.","Разведите сметану холодной водой до консистенции жидких сливок и посолите.","Смажьте круглую форму маслом и налейте тесто полосами от центра к краям, как спицы колеса.","Поставьте под верхний гриль на четыре минуты, пока слой не схватится и не пойдёт пятнами.","Сбрызните разведённой сметаной и налейте следующий слой в промежутки между предыдущими полосами.","Повторяйте, чередуя направление полос, пока тесто не кончится — обычно двадцать-двадцать пять слоёв.","Полейте растопленным маслом, дайте постоять десять минут и подавайте с йогуртом или мёдом."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker"},
  {"id":"unitools-rolex-uganda","name":"Ролекс","description":"Омлет с овощами, завёрнутый в лепёшку чапати. Уличная еда Кампалы, названная от «rolled eggs».","category":"Завтраки","tags":["угандийская кухня"],"ingredients":[["fdc-168936",400,"Мука"],["builtin-110",240,"Вода тёплая"],["fdc-171287",400.0,"Яйца"],["fdc-169975",200,"Капуста"],["fdc-170457",369.0,"Помидоры"],["fdc-170000",220.0,"Лук"],["fdc-170393",61.0,"Морковь"],["fdc-170106",45.0,"Перец чили"],["fdc-172336",110.5719,"Растительное масло"]],"servings":4,"prep":35,"cook":30,"difficulty":"Простой","steps":["Замесите мягкое тесто из муки, тёплой воды, ложки масла и соли и оставьте на двадцать минут.","Раскатайте шар тонко, смажьте маслом, сверните жгутом, закрутите улиткой и раскатайте снова.","Жарьте чапати на среднем огне по полторы минуты с каждой стороны и держите под полотенцем.","Нашинкуйте капусту, морковь, лук, помидоры и чили как можно тоньше.","Взбейте яйца с овощами, солью и перцем — овощи должны быть внутри омлета, а не сверху.","Вылейте порцию яиц на сковороду, дайте схватиться и положите сверху чапати, прижав лопаткой.","Переверните вместе, снимите на доску омлетом вверх и сверните плотным рулетом."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-muriwo-unedovi","name":"Зелень в арахисовом соусе","description":"Листовая капуста, тушённая в арахисовой пасте с помидором. Гарнир к садзе в каждом доме.","category":"Гарниры","tags":["зимбабвийская кухня"],"ingredients":[["fdc-170406",700,"Листовая капуста"],["fdc-172459",150,"Арахисовая паста"],["fdc-170000",110.0,"Лук"],["fdc-170457",369.0,"Помидоры"],["fdc-169230",9.0,"Чеснок"],["fdc-172336",36.8573,"Растительное масло"]],"servings":4,"prep":15,"cook":25,"difficulty":"Простой","steps":["Снимите с листьев жёсткие черешки, сверните листья рулоном и нарежьте тонкой соломкой.","Обжарьте лук и чеснок в масле до мягкости, пять минут.","Добавьте нарезанные помидоры и тушите семь минут, пока они не разойдутся в пасту.","Разведите арахисовую пасту стаканом горячей воды до однородности без комков.","Вмешайте зелень и разведённую пасту, посолите и тушите под крышкой двенадцать минут.","Снимите крышку и выпарите лишнюю жидкость — соус должен держаться на листьях."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-melanzane-alla-parmigiana","name":"Пармиджана из баклажанов","description":"Слои жареных баклажанов с томатным соусом, моцареллой и пармезаном, запечённые до корки.","category":"Основные блюда","tags":["итальянская кухня"],"ingredients":[["fdc-169228",1500.0,"Баклажаны"],["fdc-170051",800,"Томаты в собственном соку"],["fdc-170845",400,"Моцарелла"],["fdc-170848",150,"Пармезан"],["fdc-172232",30,"Базилик"],["fdc-169230",9.0,"Чеснок"],["fdc-171413",182.5957,"Оливковое масло"]],"servings":6,"prep":50,"cook":60,"difficulty":"Средний","steps":["Нарежьте баклажаны вдоль ломтями в полсантиметра, посолите и оставьте под грузом на полчаса.","Обсушите ломти насухо бумагой — на мокрых масло будет брызгать, а корка не образуется.","Обжарьте баклажаны партиями в оливковом масле по две минуты с каждой стороны и выложите на решётку.","Обжарьте чеснок, добавьте томаты и варите соус двадцать минут до густоты, посолив в конце.","Нарежьте моцареллу и оставьте на бумаге стекать десять минут.","Собирайте слоями: соус, баклажаны, моцарелла, пармезан, базилик — и так четыре раза.","Запекайте при 190 °C сорок минут и дайте постоять двадцать перед нарезкой."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-gemista","name":"Гемиста","description":"Помидоры и перцы, фаршированные рисом с зеленью и запечённые с картофелем в оливковом масле.","category":"Основные блюда","tags":["греческая кухня"],"ingredients":[["fdc-170457",1456.0,"Помидоры крупные"],["fdc-170108",476.0,"Перец сладкий"],["fdc-168881",300,"Рис круглозёрный"],["fdc-170000",330.0,"Лук"],["fdc-170026",600,"Картофель"],["fdc-170416",50,"Петрушка"],["fdc-173475",20,"Мята"],["fdc-172233",30,"Укроп"],["fdc-171413",182.5957,"Оливковое масло"],["fdc-169655",4.2,"Сахар"]],"servings":6,"prep":45,"cook":80,"difficulty":"Простой","steps":["Срежьте у помидоров крышечки и выберите мякоть ложкой, не повредив стенки.","Пробейте мякоть блендером и добавьте сахар — он уберёт кислоту помидоров.","Обжарьте лук в оливковом масле десять минут до мягкости и сладости.","Смешайте сырой рис с луком, зеленью, половиной томатного пюре, солью и перцем.","Наполните овощи на две трети, накройте крышечками и поставьте в форму.","Разложите между ними картофель дольками, залейте оставшимся пюре и щедро полейте маслом.","Запекайте под фольгой при 180 °C час, потом снимите фольгу и держите ещё двадцать минут."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-beef-stroganoff","name":"Бефстроганов","description":"Говядина, нарезанная соломкой и обжаренная на сильном огне, в сметанном соусе с луком.","category":"Основные блюда","tags":["русская кухня"],"ingredients":[["fdc-169542",700,"Говяжья вырезка"],["fdc-170000",220.0,"Лук"],["fdc-169251",300,"Шампиньоны"],["fdc-171257",291.6459,"Сметана"],["fdc-172234",15.5625,"Горчица"],["fdc-168936",15.625,"Мука"],["fdc-172883",202.8841,"Говяжий бульон"],["fdc-173430",60,"Сливочное масло"],["fdc-172336",27.643,"Растительное масло"],["fdc-170416",20,"Петрушка"]],"servings":4,"prep":20,"cook":25,"difficulty":"Простой","steps":["Нарежьте мясо поперёк волокон соломкой толщиной в сантиметр, обсушите бумагой и поперчите.","Раскалите сковороду и обжарьте мясо порциями по полторы минуты, не переворачивая часто.","Выньте мясо, обжарьте грибы на сильном огне до испарения их воды.","Добавьте масло и лук и жарьте до мягкости и золотистого цвета.","Всыпьте муку, прогрейте минуту и влейте бульон, размешивая до гладкости.","Снимите с огня, вмешайте сметану и горчицу и посолите.","Верните мясо с выделившимся соком, прогрейте минуту не кипятя и посыпьте петрушкой."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-chapati-kenyan","name":"Кенийская чапати","description":"Слоёная мягкая лепёшка из пшеничного теста, свёрнутого спиралью перед раскаткой.","category":"Выпечка","tags":["кенийская кухня"],"ingredients":[["fdc-168936",600,"Мука"],["builtin-110",350,"Вода тёплая"],["fdc-172336",138.2148,"Растительное масло"],["fdc-169655",12.5,"Сахар"],["fdc-173468",9.0,"Соль"]],"servings":8,"prep":75,"cook":30,"difficulty":"Средний","steps":["Смешайте муку с солью и сахаром, влейте тёплую воду и две ложки масла.","Вымешивайте тесто пятнадцать минут, пока оно не станет гладким и эластичным.","Накройте влажным полотенцем и дайте отдохнуть час при комнатной температуре.","Разделите на восемь шаров, раскатайте каждый в тонкий круг и щедро смажьте маслом.","Сверните круг в жгут, закрутите улиткой и придавите ладонью.","Дайте улиткам постоять пятнадцать минут и раскатайте каждую в круг заново.","Жарьте на сухой сковороде по полторы минуты с каждой стороны, смазывая маслом, до румяных пятен."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker"},
  {"id":"unitools-montreal-bagels","name":"Монреальские бейглы","description":"Бейглы, отваренные в медовой воде и запечённые в дровяной печи, слаще и тоньше нью-йоркских.","category":"Выпечка","tags":["канадская кухня"],"ingredients":[["fdc-168896",700,"Мука сильная"],["builtin-110",300,"Вода тёплая"],["fdc-175043",10,"Сухие дрожжи"],["fdc-171287",100.0,"Яйца"],["fdc-172336",55.2859,"Растительное масло"],["fdc-169655",60,"Сахар"],["fdc-169640",150,"Мёд"],["fdc-170150",150,"Кунжут"],["fdc-171330",100,"Мак"],["fdc-173468",6.0,"Соль"]],"servings":12,"prep":120,"cook":25,"difficulty":"Сложный","steps":["Растворите дрожжи с сахаром в тёплой воде и оставьте на десять минут до пены.","Замесите тесто из муки, опары, яиц, масла и соли и вымешивайте пятнадцать минут до эластичности.","Дайте подойти в тепле час двадцать, пока тесто не удвоится.","Разделите на двенадцать частей, раскатайте жгутами и соедините концы кольцом с крупным отверстием.","Вскипятите большую кастрюлю воды с мёдом и опускайте кольца по три-четыре штуки.","Варите по минуте с каждой стороны и сразу обваливайте в кунжуте или маке.","Пеките при 230 °C двадцать минут до тёмно-золотой корки, перевернув один раз на середине."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker"},
  {"id":"unitools-arroz-con-coco","name":"Рис с кокосом","description":"Рис на кокосовом молоке с карамелизованными шкварками кокоса, тёмный и слегка сладкий.","category":"Гарниры","tags":["панамская кухня"],"ingredients":[["fdc-168877",500,"Рис длиннозёрный"],["fdc-170173",764.1969,"Кокосовое молоко"],["builtin-110",400,"Вода"],["fdc-169655",25.0,"Сахар"],["fdc-168165",80,"Изюм"],["fdc-173468",9.0,"Соль"]],"servings":6,"prep":15,"cook":45,"difficulty":"Средний","steps":["Влейте кокосовое молоко в казан и варите на среднем огне, помешивая.","Продолжайте варить, пока молоко не разделится на масло и коричневые шкварки.","Как только шкварки станут тёмно-коричневыми, сразу влейте воду, чтобы остановить карамелизацию.","Добавьте сахар, соль и изюм и доведите до кипения.","Промойте рис до прозрачной воды и всыпьте в кастрюлю ровным слоем.","Варите на среднем огне без крышки, пока жидкость не сравняется с уровнем риса.","Накройте, убавьте огонь до минимума и держите двадцать минут, ни разу не открывая."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker"},
  {"id":"unitools-kugelis","name":"Кугелис","description":"Картофельная запеканка из тёртого сырого картофеля с беконом и луком, со сметаной.","category":"Основные блюда","tags":["литовская кухня"],"ingredients":[["fdc-170026",2000,"Картофель"],["fdc-168277",300,"Копчёная грудинка"],["fdc-170000",330.0,"Лук"],["fdc-171287",150.0,"Яйца"],["fdc-172217",206.2655,"Молоко"],["fdc-171257",291.6459,"Сметана"],["fdc-170928",0.6,"Майоран"]],"servings":8,"prep":35,"cook":95,"difficulty":"Средний","steps":["Вытопите грудинку до шкварок, добавьте нарезанный лук и жарьте до золотистого цвета.","Натрите картофель на мелкой тёрке и слегка отожмите, собрав жидкость в миску.","Дайте жидкости отстояться десять минут, слейте воду и вмешайте осевший крахмал обратно.","Влейте горячее молоко и горячий жир с луком и шкварками, размешивая быстро.","Вмешайте яйца, соль, перец и майоран до однородной густой массы.","Вылейте в смазанную форму слоем в четыре сантиметра и разровняйте.","Запекайте при 180 °C полтора часа до тёмно-золотой корки и дайте постоять двадцать минут."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль и перец."},
  {"id":"unitools-sklandrausis","name":"Складраусис","description":"Ржаная корзиночка с двумя слоями пюре — картофельным и морковным, с корицей.","category":"Десерты","tags":["латвийская кухня"],"ingredients":[["fdc-168886",400,"Ржаная мука"],["builtin-110",180,"Вода тёплая"],["fdc-173430",80,"Сливочное масло"],["fdc-170026",500,"Картофель"],["fdc-170393",600,"Морковь"],["fdc-171257",194.4306,"Сметана"],["fdc-171287",100.0,"Яйца"],["fdc-169655",80,"Сахар"],["fdc-170918",2.1,"Тмин"],["fdc-171320",2.6,"Корица"],["fdc-173468",6.0,"Соль"]],"servings":10,"prep":60,"cook":30,"difficulty":"Средний","steps":["Замесите тесто из ржаной муки, тёплой воды, растопленного масла и соли и дайте отдохнуть полчаса.","Отварите картофель и морковь по отдельности до полной мягкости.","Разомните картофель со сметаной, яйцом, тмином и солью в гладкое пюре.","Разомните морковь со сметаной, яйцом, сахаром и корицей в отдельное пюре.","Раскатайте тесто тонко, вырежьте круги и сформуйте бортики пальцами, подворачивая края.","Выложите картофельное пюре первым слоем, сверху морковное, разровняйте ложкой.","Пеките при 200 °C двадцать пять минут и посыпьте корицей ещё горячими."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker"},
  {"id":"unitools-skabu-putra","name":"Скабу путра","description":"Холодная перловая каша на кислом молоке, латвийская еда полевого дня.","category":"Супы","tags":["латвийская кухня"],"ingredients":[["fdc-170284",250,"Перловая крупа"],["builtin-110",1500.0,"Вода"],["fdc-172225",1035.5544,"Простокваша или пахта"],["fdc-171257",145.823,"Сметана"],["fdc-170005",40,"Зелёный лук"],["fdc-172233",30,"Укроп"],["fdc-170026",600,"Картофель"]],"servings":5,"prep":15,"cook":70,"difficulty":"Простой","steps":["Промойте перловку и замочите её в холодной воде на два часа.","Отварите крупу в полутора литрах воды час, пока она не разварится полностью.","Посолите кашу и полностью остудите её, помешивая, чтобы не образовалась плёнка.","Вмешайте простоквашу в холодную кашу постепенно, добиваясь консистенции густого супа.","Оставьте на четыре часа в холодном месте, чтобы вкус закислился и выровнялся.","Отварите картофель в мундире и подайте его горячим отдельно.","Разлейте по мискам, добавьте сметану и посыпьте зелёным луком и укропом."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль."},
  {"id":"unitools-gurasa","name":"Гураса","description":"Толстая суданская лепёшка на сковороде, поданная с мясным рагу или соусом.","category":"Выпечка","tags":["суданская кухня"],"ingredients":[["fdc-168936",500,"Мука"],["builtin-110",550,"Вода тёплая"],["fdc-175043",7,"Сухие дрожжи"],["fdc-169655",12.5,"Сахар"],["fdc-172336",36.8573,"Растительное масло"],["fdc-173468",6.0,"Соль"]],"servings":6,"prep":80,"cook":30,"difficulty":"Простой","steps":["Разведите дрожжи с сахаром в тёплой воде и оставьте на десять минут до пены.","Всыпьте муку с солью и размешайте венчиком до гладкого жидкого теста без комков.","Влейте масло и вымешайте ещё минуту, пока тесто не станет глянцевым.","Накройте и оставьте в тепле на час, пока по поверхности не пойдут пузыри.","Разогрейте сухую сковороду на среднем огне и вылейте половник теста.","Накройте крышкой и жарьте пять минут, пока верх не схватится и не станет матовым.","Снимите, не переворачивая, и складывайте стопкой под полотенце."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker"},
  {"id":"unitools-vitumbua","name":"Витумбуа","description":"Рисовые оладьи на кокосовом молоке, выпеченные в сковороде с полусферическими лунками.","category":"Завтраки","tags":["танзанийская кухня"],"ingredients":[["fdc-168877",400,"Рис"],["fdc-170173",286.5738,"Кокосовое молоко"],["fdc-169655",120,"Сахар"],["fdc-175043",5,"Сухие дрожжи"],["fdc-170919",2.0,"Кардамон молотый"],["fdc-170169",60,"Кокосовая стружка"],["fdc-172336",110.5719,"Растительное масло"]],"servings":8,"prep":40,"cook":30,"difficulty":"Средний","steps":["Слейте воду с замоченного риса и перемелите его с кокосовым молоком в гладкое жидкое тесто.","Вмешайте дрожжи, сахар, кардамон, соль и кокосовую стружку.","Оставьте тесто бродить четыре часа в тепле, пока оно не покроется пузырями.","Размешайте тесто и проверьте густоту: оно должно литься лентой, а не падать комом.","Разогрейте сковороду с лунками и смажьте каждую маслом с помощью кисти.","Наполните лунки на три четверти и пеките три минуты, пока края не схватятся.","Переверните оладьи шпажкой и допеките ещё три минуты до румяного шара."],"source":"UniTools — theunitools.com · CC BY-SA 4.0 · адаптация MassTracker","seasoningNote":"По вкусу, вне расчёта КБЖУ: Соль."},
];
